/// `rotationMissingGeneration` (invalidValue): A removal, or an add after a
/// rotation, when this member lacks a key generation the rotation must chain;
/// it works once an envelope for it arrives.
pub(crate) const ROTATION_MISSING_GENERATION: &str =
    "the member holds no space key of a generation the rotation must chain; it can rotate once the key envelope for that generation arrives";

/// `rotationMissingPersonKey` (invalidValue): A removal, or an add after a
/// rotation, when this member lacks a person key of the space that the rotation
/// must re-wrap; it works once it fetched the key's record.
pub(crate) const ROTATION_MISSING_PERSON_KEY: &str =
    "the member does not hold a person key of the space, which the rotation must re-wrap; it can rotate once it has fetched the key's record";

/// `signOffDoesNotHold` (invalidValue): Db::erase when one of the sign-offs
/// would not hold in its space by RFC 0008's rules; it writes no shred in any
/// space (NOC-325).
pub(crate) const SIGN_OFF_DOES_NOT_HOLD: &str =
    "a sign-off does not hold for this erasure in its space; nothing was erased";

/// `spaceClock` (storageFailed): A write (Space::write and its shorthands),
/// when the space's clock has reached its largest value, after it saw a
/// received clock at the maximum; core.clockExhausted follows.
pub(crate) fn space_clock(error: impl std::fmt::Display) -> String {
    format!("the space's clock: {error}")
}

/// `spaceOfAnotherModel` (spaceOfAnotherModel): A write to, or a read of, a
/// space whose model is not the lock's.
pub(crate) fn space_of_another_model(id: impl std::fmt::Display, space_model: impl std::fmt::Display, lock_model: impl std::fmt::Display) -> String {
    format!("the space {id} is of the model {space_model}, the lock is of the model {lock_model}")
}

/// `statementDoesNotVerify` (invalidValue): Members::add (members.add) when the
/// account key statement the invitation carries does not verify.
pub(crate) const STATEMENT_DOES_NOT_VERIFY: &str =
    "the account key statement does not verify";

/// `statementNumberTooHigh` (invalidValue): Renewing the account key, on
/// removing a lost member, when the account key statement's number cannot grow
/// further.
pub(crate) const STATEMENT_NUMBER_TOO_HIGH: &str =
    "the statement's number is too high";

/// `subAgentCreatesNoSpace` (notAllowed): Spaces::create (db.spaces.create) on
/// a sub-agent's database (OpenOptions::sub_agent): it works in the spaces its
/// parent adds it to.
pub(crate) const SUB_AGENT_CREATES_NO_SPACE: &str =
    "a sub-agent creates no space: its parent adds it to the spaces it works in";

/// `subAgentNotPaired` (notAllowed): Account::pair (db.account.pair) with a
/// sub-agent's invitation, version 3 (NOC-320 Q1).
pub(crate) const SUB_AGENT_NOT_PAIRED: &str =
    "a sub-agent is not paired into an account: its parent agent adds it to the spaces it works in";

/// `takeBackNotAllowed` (notAllowed): Erasures::take_back by a member that is
/// not an admin of the account that performed the erasure (NOC-325).
pub(crate) const TAKE_BACK_NOT_ALLOWED: &str =
    "only an admin of the performer's account takes an erasure back";

/// `takeBackNotPending` (invalidValue): Erasures::take_back with a shred that
/// is final, already finalized or taken back, or not of the space (NOC-325).
pub(crate) const TAKE_BACK_NOT_PENDING: &str =
    "the shred is not a provisional erasure of this space that can still be taken back";

/// `unknownAccount` (unknownAccount): Members::add (members.add) without a
/// fingerprint when the invitation's account is new to this database; the error
/// carries the fingerprint a person compares.
pub(crate) const UNKNOWN_ACCOUNT: &str =
    "the invitation's account is new to this database: pass its fingerprint once a person compared it";

/// `valueDoesNotFit` (invalidValue): A write whose value is not of the field's
/// type.
pub(crate) fn value_does_not_fit(field: impl std::fmt::Display, collection: impl std::fmt::Display) -> String {
    format!("the value does not fit the field {field} of {collection}")
}

/// `valueDoesNotFitBecause` (invalidValue): A write to a plugin's field whose
/// plugin refuses the value; the plugin's reason follows.
pub(crate) fn value_does_not_fit_because(field: impl std::fmt::Display, collection: impl std::fmt::Display, why: impl std::fmt::Display) -> String {
    format!("the value does not fit the field {field} of {collection}: {why}")
}

/// `viewFailed` (storageFull | storageFailed): Any call, when the local view's
/// SQLite fails: storageFull when the disk or the quota is full, storageFailed
/// otherwise; the core's error follows.
pub(crate) fn view_failed(error: impl std::fmt::Display) -> String {
    format!("the local view failed: {error}")
}

/// `webCryptoFailed` (storageFailed): nc.open in a browser when WebCrypto fails
/// to make the wrapping key or to seal the key record: what failed, and the
/// name of the error it threw, never a byte.
pub(crate) fn web_crypto_failed(what: impl std::fmt::Display, name: impl std::fmt::Display) -> String {
    format!("{what}: {name}")
}
